function verify($condition,string $label): void {if(!$condition)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label.PHP_EOL;}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);wb_schema($db);$incoming=[['code'=>'TV-FIXTURE1','values'=>[639000,'KH KIỂM THỬ','0320000000','Địa chỉ giả','DTQ26 L','','ok','C20/L','170 cm','Đã xác nhận','','']]];
[$snapshot,$sources,$added]=wb_append(wb_empty(),[],$incoming);verify($added===1&&$snapshot['sheets']['orders']['cellData'][1][2]['v']==='0320000000','preserve leading zero and receive website order');$first=wb_store($db,$snapshot,$sources,0,'fixture');verify($first['version']===1,'persist first revision');
$snapshot['sheets']['orders']['cellData'][3][0]=['f'=>'=SUM(A2:A3)','v'=>639000,'t'=>2];$snapshot['sheets']['orders']['cellData'][1][0]['s']=['bg'=>['rgb'=>'#ffff00']];$snapshot['sheets']['orders']['columnData'][0]['w']=220;wb_store($db,$snapshot,$sources,1,'fixture');$saved=wb_current($db);verify($saved['snapshot']['sheets']['orders']['cellData'][3][0]['f']==='=SUM(A2:A3)'&&$saved['snapshot']['sheets']['orders']['columnData'][0]['w']===220,'persist formulas and column formatting');
try{wb_store($db,$snapshot,$sources,1,'stale');throw new LogicException('stale save accepted');}catch(RuntimeException $e){verify($e->getCode()===409,'reject stale workbook overwrite');}verify(wb_current($db)['version']===2,'stale save leaves latest revision intact');verify((int)$db->query('SELECT count(*) FROM staff_workbook_history')->fetchColumn()===1,'save previous workbook revision');
unset($snapshot['sheets']['orders']['cellData'][1]);[$after,$afterSources,$count]=wb_append($snapshot,$sources,$incoming);verify($count===0&&!isset($after['sheets']['orders']['cellData'][1]),'deleted employee row is not reimported and source tracking stays intact');
$bad=$snapshot;$bad['sheets']['orders']['rowCount']=1000000;try{wb_validate($bad);throw new LogicException('oversized workbook accepted');}catch(RuntimeException $e){verify($e->getCode()===400,'enforce workbook limits');}echo "ALL WORKBOOK TESTS PASSED\n";
